// 使用常量对象保存特殊地区的中文名称，用于覆盖 Cloudflare 可能返回的英文城市名。
const SPECIAL_REGION_NAMES = {
  HK: '香港',
  MO: '澳门',
  TW: '台湾'
};

// 使用地区优先级函数选择展示地点，用于在城市缺失时依次回退到省份、国家或“远方”。
function getVisitorPlace(visitor) {
  return SPECIAL_REGION_NAMES[visitor.countryCode] ||
    visitor.city ||
    visitor.region ||
    visitor.country ||
    '远方';
}

// 使用预设文案对象匹配访客当地时段，用于生成无需 AI 调用的稳定欢迎语。
function createGreeting(period) {
  const greetings = {
    凌晨: '夜深了，注意休息！',
    早上: '早上好，愿你拥有美好的一天！',
    上午: '上午好，欢迎来到秘烛的博客！',
    中午: '中午好，记得按时吃饭！',
    下午: '下午好，愿你在这里有所收获！',
    晚上: '晚上好，感谢你的到访！'
  };

  return greetings[period] || '欢迎来到秘烛的博客！';
}

// 使用 DOM API 创建一行文本及高亮片段，用于避免把外部位置数据直接拼接进 innerHTML。
function createInfoLine(prefix, highlightedText, suffix = '') {
  const line = document.createElement('div');
  line.className = 'visitor-line';
  line.append(prefix);

  const highlight = document.createElement('span');
  highlight.className = 'visitor-highlight';
  highlight.textContent = highlightedText;
  line.append(highlight, suffix);

  return line;
}

// 使用多个语义化 DOM 节点渲染欢迎卡，用于分别控制标题、地点、问候语、时间和结语的样式。
function renderWelcome(element, visitor) {
  const place = getVisitorPlace(visitor);
  const localTime = visitor.localTime || '疑似掉入黑洞';


  const title = document.createElement('div');
  title.className = 'visitor-title';
  title.textContent = '🎉 欢迎信息 🎉';

  const locationLine = createInfoLine('来自 ', place, ' 的朋友');

  const greetingLine = document.createElement('div');
  greetingLine.className = 'visitor-line visitor-greeting';
  greetingLine.textContent = createGreeting(visitor.period);

  const timeLine = createInfoLine(
    '当地时间：',
    localTime || '疑似掉入黑洞'
  );

  const endingLine = document.createElement('div');
  endingLine.className = 'visitor-ending';
  endingLine.textContent = '欢迎来到秘烛的博客';

  element.replaceChildren(
    title,
    locationLine,
    greetingLine,
    timeLine,
    endingLine
  );
}

// 使用异步 IIFE 在页面加载后请求 Cloudflare Worker，用于获取访客的大致地区与当地时间并立即渲染。
(async () => {
  const element = document.getElementById('visitor-welcome');

  // 使用空值检查提前结束，用于兼容没有公告卡片的页面。
  if (!element) return;

  try {
    // 使用 Fetch API 调用 Cloudflare Worker，用于读取不包含完整 IP 的国家、城市和当地时间数据。
    const response = await fetch(
      'https://miizhu-visitor-location.miizhuan.workers.dev'
    );

    // 使用 HTTP 状态检查主动抛错，用于统一进入下方的失败回退逻辑。
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    // 使用 JSON 解析和渲染函数更新页面，用于显示分行且带颜色的个性化欢迎信息。
    const visitor = await response.json();
    renderWelcome(element, visitor);
  } catch (error) {
    // 使用纯文本回退内容处理网络或接口异常，用于保证公告区域始终有可读信息。
    element.textContent = '欢迎来到秘烛的博客！';
    console.error('欢迎语加载失败：', error);
  }
})();

(() => {
  // 网站正式开始运行的时间，+08:00 表示北京时间
  const startTime = new Date('2026-08-02T03:05:00+08:00').getTime();

  function updateRuntime() {
    const element = document.getElementById('site-runtime');

    if (!element) return;

    const difference = Math.max(0, Date.now() - startTime);
    const totalSeconds = Math.floor(difference / 1000);

    const days = Math.floor(totalSeconds / 86400);
    const hours = Math.floor((totalSeconds % 86400) / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    element.textContent =
      `${days} 天 ${String(hours).padStart(2, '0')} 小时 ` +
      `${String(minutes).padStart(2, '0')} 分 ${String(seconds).padStart(2, '0')} 秒`;
  }

  updateRuntime();
  setInterval(updateRuntime, 1000);

  // 从后台标签页切回时立即校正时间
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) updateRuntime();
  });
})();

/* 隐藏导航栏菜单项的下拉箭头 */
#nav .menus_items .site-page.has-dropdown::after {
    display: none !important;
}

#web_bg {
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important; /* 核心属性：让背景固定，不随滚动条移动 */
  background-position: center !important;
}

#post {
    /* 1. 宽度调整 */
    /* 修复了之前的拼写错误 (widht -> width) */
    max-width: 12000px !important; /* 建议不要超过屏幕宽度的80%，否则阅读体验不好 */
    width: 90% !important;        /* 在小屏幕上保持边距 */

    /* 2. 透明度与背景调整 */
    /* 0.85 代表 85% 的不透明度，看起来是纯白偏透，没有模糊感 */
    background: rgba(255, 255, 255, 0.85) !important;

    /* 3. 彻底移除毛玻璃效果 */
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;

    /* 4. 保持圆角和间距 */
    border-radius: 16px !important;
    padding: 50px !important;
    margin: 30px auto !important;
}

.note {
    border-radius: 12px !important;
    /* 不强制覆盖 background，只增加一点通透感 */
    /* 利用 mix-blend-mode 或者降低不透明度来融合背景 */
    opacity: 0.85 !important; /* 整体稍微透明一点点 */
}

/* 文章正文默认字号 */
#article-container {
  font-size: 18px;
  line-height: 1.8;
}

/* 移动端字号 */
@media screen and (max-width: 768px) {
  #article-container {
    font-size: 16px;
    line-height: 1.75;
  }
}
/* 全站动态视频背景 */
#video-background {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  z-index: -999;
  pointer-events: none;
}

/* 禁用 Butterfly 原来的背景层 */
#web_bg {
  background: transparent !important;
}

@media screen and (max-width: 768px),
       (prefers-reduced-motion: reduce) {
  #video-background {
    display: none !important;
  }
/* 为手机和减少动画模式保留静态背景 */
  #web_bg {
    background:
      url("https://cdn.jsdelivr.net/gh/Miizhu/picgo@main/images/mainpage.jpg")
      center / cover no-repeat fixed !important;
  }

  body::before {
    display: none;
  }
}


/* 使用居中排版和舒适行高，用于统一欢迎信息各行的字体大小、间距与基础颜色。 */
.visitor-welcome {
  padding: 6px 2px 10px;
  color: #555;
  font-size: 17px;
  line-height: 1.9;
  text-align: center;
}

/* 使用红色粗体标题和下边距，用于突出“欢迎信息”并与正文建立视觉层级。 */
.visitor-title {
  margin-bottom: 7px;
  color: #ff3030;
  font-size: 21px;
  font-weight: 700;
}

/* 使用块级行间距，用于让地点、问候语和当地时间保持整齐的分行布局。 */
.visitor-line {
  margin: 2px 0;
}

/* 使用蓝色、半粗体和等宽数字特性，用于突出地点与时间并减少秒数变化时的文字抖动。 */
.visitor-highlight {
  color: #49a6f2;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* 使用较深正文颜色，用于让根据时段生成的欢迎语成为卡片中的主要阅读内容。 */
.visitor-greeting {
  color: #555;
}

/* 使用顶部间距和中等字重，用于在卡片底部形成简洁稳定的结束语。 */
.visitor-ending {
  margin-top: 3px;
  color: #555;
  font-weight: 500;
}

/* 使用分隔线和较小字号，用于区分动态欢迎信息与原有博客公告说明。 */
.announcement-description {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid rgba(73, 166, 242, 0.2);
  color: #666;
  font-size: 14px;
  line-height: 1.7;
  text-align: center;
}

/* 使用 Butterfly 深色主题选择器调整卡片和文字颜色，用于保证夜间模式下的对比度与可读性。 */

[data-theme="dark"] .visitor-welcome,
[data-theme="dark"] .visitor-greeting,
[data-theme="dark"] .visitor-ending {
  color: #ddd;
}

[data-theme="dark"] .visitor-highlight {
  color: #75bdff;
}

[data-theme="dark"] .announcement-description {
  border-top-color: rgba(117, 189, 255, 0.22);
  color: #bbb;
}

/* 使用响应式媒体查询缩小字号和内边距，用于避免欢迎信息在手机端发生横向溢出。 */
@media screen and (max-width: 768px) {
  .visitor-welcome {
    padding-inline: 0;
    font-size: 15px;
    line-height: 1.8;
  }

  .visitor-title {
    font-size: 19px;
  }

  .announcement-description {
    font-size: 13px;
  }
}
